ttom:12px;border-radius:10px;font-size:9px;background:rgba(49,191,139,.1);color:#a8e5ca}.error-notice{background:rgba(210,65,65,.12);color:#ffb0b0}@media(max-width:1050px){.builder-grid{grid-template-columns:1fr}.edit-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:700px){.builder-card{padding:13px}.builder-toolbar{align-items:flex-start;flex-direction:column}.toolbar-actions{width:100%;justify-content:space-between}.desktop-tip{display:none}.edit-grid{grid-template-columns:1fr}.menu-card-meta,.menu-card-url{margin-left:0;padding-left:0}.nest-hint{margin-left:0}.inline-label-edit form{margin-left:0}.item-actions .move-btn{display:none}.mode-tabs a{flex:1;justify-content:center}}
