@push('scripts')<script>
(function(){
const tree=document.getElementById('menu-tree');if(!tree)return;
const reorderUrl=@json(route('admin.menu-builder.reorder')),csrf=@json(csrf_token()),menu=@json($menu),state=document.getElementById('save-state'),saveButton=document.getElementById('save-tree'),root=document.getElementById('root-drop-zone');
let dragged=null,saveTimer=null,saving=false,pending=false;
function stateSet(type,text){state.className='save-indicator '+type;state.innerHTML='<i class="fa-solid '+(type==='saving'?'fa-spinner fa-spin':type==='error'?'fa-triangle-exclamation':'fa-circle-check')+'"></i><span>'+text+'</span>'}
function rows(c){return Array.from(c.children).filter(x=>x.classList.contains('menu-row'))}
function childBox(r){let c=Array.from(r.children).find(x=>x.classList.contains('menu-children'));if(!c){c=document.createElement('div');c.className='menu-children';c.dataset.parentId=r.dataset.id;r.appendChild(c)}return c}
function isDescendant(source,targetId){return !!source.querySelector('.menu-row[data-id="'+CSS.escape(String(targetId))+'"]')}
function clearMarks(){document.querySelectorAll('.drop-before,.drop-after,.drop-inside,.drop-active').forEach(x=>x.classList.remove('drop-before','drop-after','drop-inside','drop-active'))}
function buildPayload(){const payload=[];function walk(container,parent){rows(container).forEach((row,index)=>{payload.push({id:Number(row.dataset.id),parent_id:parent===null?null:Number(parent),sort_order:index});const children=Array.from(row.children).find(x=>x.classList.contains('menu-children'));if(children)walk(children,Number(row.dataset.id))})}walk(tree,null);return payload}
async function persist(){if(saving){pending=true;return}const payload=buildPayload();saving=true;pending=false;stateSet('saving','Saving structure…');if(saveButton)saveButton.disabled=true;const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),10000);try{const response=await fetch(reorderUrl,{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':csrf,'X-Requested-With':'XMLHttpRequest'},credentials:'same-origin',body:JSON.stringify({menu,tree:payload}),signal:controller.signal});const text=await response.text();let data={};try{data=JSON.parse(text)}catch(_){}if(!response.ok||data.ok!==true)throw new Error(data.message||('Save failed (HTTP '+response.status+').'));stateSet('','All changes saved')}catch(error){stateSet('error',error.name==='AbortError'?'Save timed out. Please try again.':(error.message||'Save failed.'))}finally{clearTimeout(timeout);saving=false;if(saveButton)saveButton.disabled=false;if(pending)persist()}}
function scheduleSave(){clearTimeout(saveTimer);saveTimer=setTimeout(persist,250)}
function moveRelative(row,offset){const sibling=offset<0?row.previousElementSibling:row.nextElementSibling;if(!sibling||!sibling.classList.contains('menu-row'))return;row.parentElement.insertBefore(row,offset<0?sibling:sibling.nextSibling);scheduleSave()}
function bindRows(){document.querySelectorAll('.menu-row[draggable="true"]').forEach(row=>{row.addEventListener('dragstart',event=>{dragged=row;row.classList.add('dragging');row.setAttribute('aria-grabbed','true');event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/plain',row.dataset.id)});row.addEventListener('dragend',()=>{row.classList.remove('dragging');row.setAttribute('aria-grabbed','false');dragged=null;clearMarks()});row.addEventListener('dragover',event=>{if(!dragged||dragged===row||isDescendant(dragged,row.dataset.id))return;event.preventDefault();event.stopPropagation();clearMarks();if(row.dataset.kind==='folder'&&event.altKey)row.classList.add('drop-inside');else if(event.clientY<row.getBoundingClientRect().top+row.getBoundingClientRect().height/2)row.classList.add('drop-before');else row.classList.add('drop-after')});row.addEventListener('drop',event=>{if(!dragged||dragged===row||isDescendant(dragged,row.dataset.id))return;event.preventDefault();event.stopPropagation();if(row.dataset.kind==='folder'&&event.altKey){childBox(row).appendChild(dragged)}else if(event.clientY<row.getBoundingClientRect().top+row.getBoundingClientRect().height/2){row.parentElement.insertBefore(dragged,row)}else{row.parentElement.insertBefore(dragged,row.nextSibling)}clearMarks();scheduleSave()})})}
function bindChildren(){document.querySelectorAll('.menu-children').forEach(container=>{container.addEventListener('dragover',event=>{if(!dragged)return;event.preventDefault();event.stopPropagation();container.classList.add('drop-active')});container.addEventListener('dragleave',event=>{if(event.relatedTarget&&container.contains(event.relatedTarget))return;container.classList.remove('drop-active')});container.addEventListener('drop',event=>{if(!dragged)return;event.preventDefault();event.stopPropagation();if(container.closest('.menu-row')===dragged)return;container.appendChild(dragged);container.classList.remove('drop-active');clearMarks();scheduleSave()})})}
root.addEventListener('dragover',event=>{if(!dragged)return;event.preventDefault();event.stopPropagation();root.classList.add('drop-active')});root.addEventListener('dragleave',()=>root.classList.remove('drop-active'));root.addEventListener('drop',event=>{if(!dragged)return;event.preventDefault();event.stopPropagation();tree.appendChild(dragged);root.classList.remove('drop-active');clearMarks();scheduleSave()});
document.querySelectorAll('.move-up').forEach(button=>button.addEventListener('click',()=>{const row=document.querySelector('.menu-row[data-id="'+CSS.escape(button.dataset.id)+'"]');if(row)moveRelative(row,-1)}));document.querySelectorAll('.move-down').forEach(button=>button.addEventListener('click',()=>{const row=document.querySelector('.menu-row[data-id="'+CSS.escape(button.dataset.id)+'"]');if(row)moveRelative(row,1)}));if(saveButton)saveButton.addEventListener('click',persist);
bindRows();bindChildren();
const buttons=document.querySelectorAll('.add-mode-btn'),kind=document.getElementById('kind'),select=document.getElementById('source-select'),key=document.getElementById('source-key'),sf=document.getElementById('source-fields'),uf=document.getElementById('url-fields'),ff=document.getElementById('folder-fields'),add=document.getElementById('add-button'),ul=document.getElementById('url-label'),uv=document.getElementById('url-value'),fl=document.getElementById('folder-label'),sp=document.getElementById('source-preview'),up=document.getElementById('url-preview');
function valid(){const ok=kind.value==='source'?!!select.value:kind.value==='url'?!!ul.value.trim()&&!!uv.value.trim():!!fl.value.trim();add.disabled=!ok}
function mode(m){kind.value=m;buttons.forEach(b=>b.classList.toggle('active',b.dataset.mode===m));sf.classList.toggle('is-hidden',m!=='source');uf.classList.toggle('is-hidden',m!=='url');ff.classList.toggle('is-hidden',m!=='folder');select.required=m==='source';ul.required=m==='url';uv.required=m==='url';fl.required=m==='folder';valid()}
buttons.forEach(b=>b.addEventListener('click',()=>mode(b.dataset.mode)));select.addEventListener('change',()=>{key.value=select.value;const option=select.selectedOptions[0];sp.innerHTML=option?.value?'<strong>'+option.dataset.label+'</strong><span>'+option.dataset.url+'</span>':'Select a destination to continue.';valid()});[ul,uv,fl].forEach(input=>input.addEventListener('input',()=>{if(input===uv)up.textContent=uv.value.trim()||'Enter a URL to preview it.';valid()}));
})();
</script>@endpush
